PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,phone TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'USER' CHECK(role IN ('USER','SUPPORT','SUPER ADMIN')),status TEXT NOT NULL DEFAULT 'Active',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_login TEXT,conversation_limit INTEGER NOT NULL DEFAULT 100,deleted_at TEXT,privacy_at TEXT,session_version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS accounts(id INTEGER PRIMARY KEY,owner_id INTEGER NOT NULL REFERENCES users(id),phone TEXT NOT NULL UNIQUE,kind TEXT NOT NULL CHECK(kind IN ('Personal','Business')),phone_id TEXT UNIQUE,waba_id TEXT,status TEXT NOT NULL DEFAULT 'Disconnected',linked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,consent_at TEXT,consent_version TEXT,token_key TEXT);
CREATE TABLE IF NOT EXISTS grants(user_id INTEGER NOT NULL REFERENCES users(id),account_id INTEGER NOT NULL REFERENCES accounts(id),can_send INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,account_id));
CREATE TABLE IF NOT EXISTS conversations(id INTEGER PRIMARY KEY,account_id INTEGER NOT NULL REFERENCES accounts(id),contact TEXT NOT NULL,contact_name TEXT NOT NULL,last_activity TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_inbound INTEGER,UNIQUE(account_id,contact));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,conversation_id INTEGER NOT NULL REFERENCES conversations(id),meta_id TEXT UNIQUE,direction TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,status TEXT NOT NULL DEFAULT 'received');
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,actor_id INTEGER,action TEXT NOT NULL,target TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS subscriptions(user_id INTEGER PRIMARY KEY REFERENCES users(id),plan TEXT NOT NULL DEFAULT 'Free',status TEXT NOT NULL DEFAULT 'Active',expires_at TEXT);
CREATE TABLE IF NOT EXISTS attempts(key TEXT PRIMARY KEY,count INTEGER NOT NULL,started INTEGER NOT NULL);
